{"command":"python3 - <<'EOF'
import re, json
data = open('/tmp/tbench.html', encoding='utf-8').read()
chunks = re.findall(r'self\.__next_f\.push\(\[1,\s*(?:"((?:[^"\\]|\\.)*)")?\s*\]\)', data)
s = None
for c in chunks:
    if not c: continue
    t = c.encode().decode('unicode_escape')
    if '"leaderboard"' in t and 'queries' in t:
        s = t
dec = json.JSONDecoder()
d, end = dec.raw_decode(s[s.find('{'):])
qs = d['state']['queries']
print("num queries:", len(qs))
def brief(k):
    try: return json.dumps(k)
    except: return str(k)
for q in qs:
    print("QUERYKEY:", brief(q.get('queryKey')))
    st = q['state'].get('data')
    if isinstance(st, dict):
        print("  keys:", list(st.keys()))
        lb = st.get('leaderboard') or st.get('data',{}).get('leaderboard') if isinstance(st.get('data'), dict) else None
        for k,v in st.items():
            if isinstance(v, list):
                print(f"  list {k}: {len(v)} items; first:", json.dumps(v[0])[:300] if v else None)
            elif isinstance(v, dict):
                print(f"  dict {k}: keys {list(v.keys())}")
EOF"}

