    """-> (fetch doc or None, used_snapshot). None = no rows available."""
    import json

    if offline:
        snap = SNAPSHOT_DIR / f"{version}.json"
        if snap.exists():
            return json.loads(snap.read_text()), True
        return None, True

arguments.oldText:
def _official_for_version(version: str, offline: bool) -> "tuple[dict | None, bool]":
    """-> (fetch doc or None, used_snapshot). None = no rows available."""
    if offline:
        snap = SNAPSHOT_DIR / f"{version}.json"
        if snap.exists():
            return fetch.normalize_hub_payload(
                {"leaderboard": {}, "rows": []}, version
            ) | {} or __import__("json").loads(snap.read_text()), True
        return None, True

